const input = $json.body || $json || {};
const datos = input.datos || {};
const nombre = datos.nombre || 'Productor';
const resetUrl = datos.resetUrl || '#';
const email = datos.email || '';

const asunto = '🔑 Recuperar contraseña - AgroTech';
const html = '<h2>🔑 Recuperar contraseña</h2>' +
  '<p>Hola ' + nombre + ',</p>' +
  '<p>Recibimos un pedido para restablecer tu contraseña de AgroTech. Si fuiste vos, hacé clic en el siguiente link (válido por 1 hora):</p>' +
  '<p><a href="' + resetUrl + '" style="background:#059669;color:white;padding:12px 20px;border-radius:8px;text-decoration:none;font-weight:bold;display:inline-block;">Restablecer contraseña</a></p>' +
  '<p>Si el botón no funciona, copiá y pegá este link en el navegador:</p>' +
  '<p>' + resetUrl + '</p>' +
  '<p>Si no pediste este cambio, podés ignorar este correo — tu contraseña sigue siendo la misma.</p>';

return [{ json: { email, asunto, html } }];
